x}.medal{font-weight:700;color:var(--accent-ink);font-size:19px}.self{background:var(--surface-2)}.more{display:block;margin:20px auto}.ranking-note{font-size:11px;line-height:1.7;color:var(--muted);text-align:center}@media(max-width:600px){.ranking-panel{padding:16px}.my-rank{gap:22px;flex-wrap:wrap;padding:18px}.my-rank p{margin:0;font-size:12px}.ranking-head h2{font-size:16px}.ranking-head button{padding:8px;font-size:11px}.period-tabs{flex-wrap:wrap}.period-tabs>span{margin:0;width:100%}.reward-preview{align-items:flex-start;flex-direction:column;gap:8px}.rank-table small{display:none}.rank-table th,.rank-table td{padding:13px 4px;font-size:12px}.my-rank strong{font-size:21px}}
